llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C74"],
      "claim": "Disopyramide, the closest structural analogue sharing the 2-pyridyl phenyl carbinol core and a basic amine side chain, has an oral bioavailability of roughly 80% in patients, directly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Methadone, a lipophilic basic tertiary amine, has an absolute oral bioavailability of 0.85 in healthy volunteers, supporting high F for the query's similar lipophilic amine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "The highest-transfer analogue vismodegib has a measured absolute bioavailability of 31.8% in humans, above the 20% threshold, supporting high F despite saturable absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C55"],
      "claim": "Encainide, a basic drug with substantial first-pass metabolism, still has an absolute oral bioavailability of 20-30% in healthy subjects, at or above the threshold and supportive of high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Bosentan has an absolute oral bioavailability of approximately 50% in healthy adults, supporting high F for the query despite moderate clearance.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C54"],
      "claim": "Atazanavir has an oral bioavailability of 60-68% in humans, supporting high F for a lipophilic nitrogen-containing drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Meperidine has an absolute bioavailability of 0.63 in healthy volunteers, supporting high F for a basic tertiary amine with first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Pritelivir shows 75% oral bioavailability after a single oral dose, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Medifoxamine has an absolute bioavailability of 21% in young volunteers, just above the threshold, supporting high F while indicating some first-pass liability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Dextromoramide, a structurally related diphenylmethane basic amine, has good oral bioavailability, supporting high F for the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferable experimental evidence points to oral bioavailability at or above 20%; the closest structural analogue disopyramide has F ~80%, and methadone-like and other lipophilic basic amine analogues also show high F. No affirmative evidence supports F < 20%.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement exists for the query molecule.",
    "Some analogues such as encainide and medifoxamine have F near 20-30%, indicating first-pass metabolism could be substantial, though still above the threshold.",
    "No specific evidence addresses transporter-mediated efflux or solubility-limited absorption for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

